{
  "meta": {
    "name": "Helpdesk",
    "description": "A customer support helpdesk application for managing tickets, with features for users, agents, managers, and premium users with SLA tracking."
  },
  "entities": [
    {
      "name": "Ticket",
      "ownable": true,
      "fields": [
        {
          "name": "subject",
          "type": "string",
          "required": true
        },
        {
          "name": "description",
          "type": "text",
          "required": true
        },
        {
          "name": "priority",
          "type": "enum",
          "required": true,
          "enumValues": [
            "low",
            "medium",
            "high"
          ],
          "default": "medium"
        },
        {
          "name": "status",
          "type": "enum",
          "required": true,
          "enumValues": [
            "open",
            "in_progress",
            "resolved",
            "closed"
          ],
          "default": "open"
        }
      ],
      "relations": [
        {
          "name": "assignedAgent",
          "kind": "manyToOne",
          "target": "User",
          "required": false
        }
      ]
    },
    {
      "name": "User",
      "fields": [
        {
          "name": "name",
          "type": "string",
          "required": true
        },
        {
          "name": "email",
          "type": "email",
          "required": true,
          "unique": true
        },
        {
          "name": "role",
          "type": "enum",
          "required": true,
          "enumValues": [
            "user",
            "agent",
            "manager"
          ],
          "default": "user"
        }
      ]
    },
    {
      "name": "Sla",
      "fields": [
        {
          "name": "targetResponseTime",
          "type": "integer",
          "required": true
        },
        {
          "name": "targetResolutionTime",
          "type": "integer",
          "required": true
        },
        {
          "name": "startTime",
          "type": "datetime",
          "required": true
        },
        {
          "name": "endTime",
          "type": "datetime"
        },
        {
          "name": "violated",
          "type": "boolean",
          "default": false
        }
      ],
      "relations": [
        {
          "name": "ticket",
          "kind": "manyToOne",
          "target": "Ticket",
          "required": true
        }
      ]
    }
  ],
  "roles": [
    {
      "name": "user",
      "description": "Can submit tickets.",
      "isDefault": true
    },
    {
      "name": "agent",
      "description": "Can respond to tickets and change status."
    },
    {
      "name": "manager",
      "description": "Can view ticket analytics."
    },
    {
      "name": "premiumUser",
      "description": "Has access to SLA tracking."
    }
  ],
  "permissions": [
    {
      "role": "user",
      "entity": "Ticket",
      "actions": [
        "create",
        "read"
      ],
      "scope": "own"
    },
    {
      "role": "agent",
      "entity": "Ticket",
      "actions": [
        "read",
        "update"
      ],
      "scope": "all"
    },
    {
      "role": "manager",
      "entity": "Ticket",
      "actions": [
        "read"
      ],
      "scope": "all"
    },
    {
      "role": "premiumUser",
      "entity": "Sla",
      "actions": [
        "create",
        "read",
        "update"
      ],
      "scope": "all"
    }
  ],
  "pages": [
    {
      "name": "My Tickets",
      "route": "/tickets",
      "type": "list",
      "entity": "Ticket",
      "access": [
        "user",
        "agent",
        "manager"
      ],
      "fields": [
        "subject",
        "priority",
        "status",
        "createdAt"
      ]
    },
    {
      "name": "New Ticket",
      "route": "/tickets/new",
      "type": "form",
      "entity": "Ticket",
      "access": [
        "user"
      ]
    },
    {
      "name": "Ticket Detail",
      "route": "/tickets/:id",
      "type": "detail",
      "entity": "Ticket",
      "access": [
        "user",
        "agent",
        "manager"
      ]
    },
    {
      "name": "Agent Dashboard",
      "route": "/agent/dashboard",
      "type": "dashboard",
      "access": [
        "agent"
      ],
      "widgets": [
        {
          "type": "table",
          "label": "Open Tickets",
          "entity": "Ticket",
          "filter": {
            "status": "open"
          }
        }
      ]
    },
    {
      "name": "Manager Dashboard",
      "route": "/manager/dashboard",
      "type": "dashboard",
      "access": [
        "manager"
      ],
      "widgets": [
        {
          "type": "stat",
          "label": "Total Tickets",
          "entity": "Ticket",
          "metric": "count"
        },
        {
          "type": "stat",
          "label": "Open Tickets",
          "entity": "Ticket",
          "metric": "count",
          "filter": {
            "status": "open"
          }
        },
        {
          "type": "stat",
          "label": "Closed Tickets",
          "entity": "Ticket",
          "metric": "count",
          "filter": {
            "status": "closed"
          }
        },
        {
          "type": "chart",
          "label": "Tickets by Priority",
          "entity": "Ticket",
          "chartType": "bar",
          "groupBy": "priority",
          "metric": "count"
        }
      ]
    },
    {
      "name": "SLA Tracking",
      "route": "/sla",
      "type": "list",
      "entity": "Sla",
      "access": [
        "premiumUser"
      ],
      "requiresPlan": "premium",
      "fields": [
        "ticket.subject",
        "targetResponseTime",
        "targetResolutionTime",
        "startTime",
        "endTime",
        "violated"
      ]
    }
  ],
  "plans": [
    {
      "name": "free",
      "price": 0,
      "isDefault": true,
      "features": [
        "ticketManagement",
        "userManagement",
        "analytics",
        "roleBasedAccess"
      ]
    },
    {
      "name": "premium",
      "price": 10,
      "interval": "month",
      "features": [
        "slaTracking"
      ]
    }
  ],
  "businessRules": [
    {
      "type": "plan_gate",
      "id": "slaTrackingGate",
      "requiresPlan": "premium",
      "gates": {
        "pages": [
          "SLA Tracking"
        ],
        "features": [
          "slaTracking"
        ]
      }
    },
    {
      "type": "ownership",
      "id": "ticketOwnership",
      "entity": "Ticket"
    },
    {
      "type": "ownership",
      "id": "slaOwnership",
      "entity": "Sla"
    }
  ],
  "auth": {
    "strategy": "email_password",
    "requireAuth": true
  }
}
